class HubSpotError extends Error {
  constructor(code, { status = null, retryable = false, cause } = {}) {
    super(code, { cause });
    this.name = 'HubSpotError';
    this.code = code;
    this.status = status;
    this.retryable = retryable;
  }
}
function objectId(value) {
  const id = String(value ?? '');
  if (!/^\d+$/.test(id)) throw new HubSpotError('invalid_hubspot_object_id');
  return id;
}
function contactRecordUrl(portalId, contactId) {
  return `https://app.hubspot.com/contacts/${objectId(portalId)}/record/0-1/${objectId(contactId)}`;
}
function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}
function row(label, value) {
  return `<tr><th align="left" style="padding:6px 12px 6px 0">${escapeHtml(label)}</th><td>${escapeHtml(value || 'No informado')}</td></tr>`;
}
const LABELS = {"high_fit":"Buen encaje sugerido","possible_fit":"Encaje posible","low_fit":"Bajo encaje sugerido","insufficient_information":"Información insuficiente"};
